input.script:
listing = boundary retry 3 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, listing.total_pages + 1) {
    result = boundary retry 3 {
        return list_orders({ month: "2026-03", page: page })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
orders = fold acc = listing.items for page_items in remaining {
    return acc + page_items
}
enriched = for o in orders {
    detail = boundary retry 3 {
        return get_order({ id: o.id })
    } catch err {
        return fail("GET_ORDER_FAILED", err.code + ": " + err.message)
    }
    skip if detail.status != "completed"
    customer = boundary retry 3 {
        return get_customer({ id: o.customer_id })
    } catch err {
        return fail("GET_CUSTOMER_FAILED", err.code + ": " + err.message)
    }
    return {
        region: customer.region,
        amount_cents: detail.amount_cents
    }
}
totals = fold acc = { NA: 0, EU: 0, APAC: 0 } for row in enriched {
    return acc + { [row.region]: acc[row.region] + row.amount_cents }
}
submitted = submit_result({ answer: totals })
return { totals: totals, recorded: submitted.recorded }

first = boundary retry 3 {
    return list_orders({ month: "2026-03", page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
page_lists = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 3 {
        return list_orders({ month: "2026-03", page: page })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
orders = fold acc = first.items for items in page_lists {
    return acc + items
}
enriched = for o in orders {
    detail = boundary retry 3 {
        return get_order({ id: o.id })
    } catch err {
        return fail("GET_ORDER_FAILED", err.code + ": " + err.message)
    }
    skip if detail.status != "completed"
    cust = boundary retry 3 {
        return get_customer({ id: o.customer_id })
    } catch err {
        return fail("GET_CUSTOMER_FAILED", err.code + ": " + err.message)
    }
    return {
        region: cust.region,
        amount: detail.amount_cents
    }
}
na = fold acc = 0 for row in enriched {
    return acc + (row.amount if row.region == "NA" else 0)
}
eu = fold acc = 0 for row in enriched {
    return acc + (row.amount if row.region == "EU" else 0)
}
apac = fold acc = 0 for row in enriched {
    return acc + (row.amount if row.region == "APAC" else 0)
}
answer = { NA: na, EU: eu, APAC: apac }
submitted = submit_result({ answer: answer })
return { answer: answer, recorded: submitted.recorded }
